import{_ as a,o as e,c as o,a2 as i}from"./chunks/framework.CfwCq2QB.js";const l="/dev-go-docs/shots/0.2.3/zh-CN/light/sidepanel.png",r="/dev-go-docs/shots/0.2.3/zh-CN/dark/sidepanel.png",_=JSON.parse('{"title":"AI 助手","description":"","frontmatter":{},"headers":[],"relativePath":"features/assistant.md","filePath":"features/assistant.md"}'),d={name:"features/assistant.md"};function s(c,t,n,h,m,p){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="ai-助手" tabindex="-1">AI 助手 <a class="header-anchor" href="#ai-助手" aria-label="Permalink to &quot;AI 助手&quot;">​</a></h1><p>一句话：侧边栏 AI 助手（<code>Alt+2</code> 打开 / 关闭），一键总结本页、提取要点，就网页内容提问，AI 会自行读取网页正文；划词「问 AI」也会带着选中内容过来。</p><h2 id="打开方式" tabindex="-1">打开方式 <a class="header-anchor" href="#打开方式" aria-label="Permalink to &quot;打开方式&quot;">​</a></h2><ul><li>快捷键 <code>Alt+2</code>（macOS 为 <code>⌥2</code>），再按一次关闭</li><li>弹窗「功能」页 → AI 助手 →「打开」</li><li>悬浮快捷栏 →「AI 助手」或「AI 总结本页」</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>Alt+2</code> 是 Chrome 专有快捷键；Firefox 的侧边栏由浏览器自身控制，从弹窗或悬浮快捷栏打开即可。</p></div><h2 id="快捷指令" tabindex="-1">快捷指令 <a class="header-anchor" href="#快捷指令" aria-label="Permalink to &quot;快捷指令&quot;">​</a></h2><p>侧边栏顶部内置三个快捷指令，点一下就带着当前网页开问：</p><table tabindex="0"><thead><tr><th>指令</th><th>做什么</th></tr></thead><tbody><tr><td>总结本页</td><td>先一两句话概括，再分点列出关键信息</td></tr><tr><td>提取要点</td><td>列出结论、数据、步骤、注意事项等关键信息</td></tr><tr><td>用中文讲讲</td><td>用简体中文介绍这个网页讲了什么、适合谁看</td></tr></tbody></table><h2 id="对话" tabindex="-1">对话 <a class="header-anchor" href="#对话" aria-label="Permalink to &quot;对话&quot;">​</a></h2><ul><li>AI 会自动读取当前网页正文（包括 Shadow DOM 渲染的页面），不用手动复制粘贴</li><li>回答流式输出，支持展开查看<strong>思考过程</strong></li><li>划词「问 AI」会把选中内容作为引用带进来，也可以输入框上方手动「移除引用」</li><li>网页提供了 WebMCP 工具时，AI 可以直接调用工具在网页上操作（见<a href="/dev-go-docs/features/webmcp.html">网页工具</a>），执行过程以卡片形式显示在对话里</li></ul><p>输入框：<code>Enter</code> 发送，<code>Shift + Enter</code> 换行；生成过程中可以点「停止」。</p><img src="'+l+'" alt="侧边栏 AI 助手" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：侧边栏 AI 助手——顶部快捷指令，输入框直接就当前网页提问。</em></p><img src="'+r+'" alt="深色侧边栏" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：深色主题下的侧边栏。</em></p><h2 id="模型配置" tabindex="-1">模型配置 <a class="header-anchor" href="#模型配置" aria-label="Permalink to &quot;模型配置&quot;">​</a></h2><p>助手使用<a href="/dev-go-docs/settings/models.html">对话模型</a>（与翻译模型分开配置）：建议选能力强、支持工具调用的模型。侧边栏右上角「设置」可以直达配置，也可以追加自定义要求（如「回答尽量简短」）。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>未配置模型时输入框会提示「先在设置里配置对话模型」</li><li>浏览器内置页面（<code>chrome://</code> 开头）无法读取正文；安装扩展前就打开的页面，刷新一次即可</li></ul>',19)])])}const f=a(d,[["render",s]]);export{_ as __pageData,f as default};
